  function closePhfModal(value){var root=document.getElementById('phfSystemModal');if(root)root.remove();var r=PHF_MODAL_RESOLVE;PHF_MODAL_RESOLVE=null;if(r)r(!!value)}
  function phfDialog(message,options){ensureAdminUi();options=options||{};var old=document.getElementById('phfSystemModal');if(old)old.remove();return new Promise(function(resolve){PHF_MODAL_RESOLVE=resolve;var root=document.createElement('div');root.id='phfSystemModal';root.className='phf-modal-backdrop';root.innerHTML='<div class="phf-modal-card '+(options.tone||'')+'" role="dialog" aria-modal="true"><div class="phf-modal-head"><div class="phf-modal-icon">'+(options.icon||'PHF')+'</div><div><h3>'+esc(options.title||'Thông báo')+'</h3><p>'+esc(message||'')+'</p></div></div><div class="phf-modal-actions">'+(options.confirm?'<button class="phf-modal-btn" type="button" onclick="closePhfModal(false)">'+esc(options.cancelText||'Hủy')+'</button>':'')+'<button class="phf-modal-btn primary" type="button" onclick="closePhfModal(true)">'+esc(options.okText||'Đồng ý')+'</button></div></div>';root.addEventListener('click',function(e){if(e.target===root&&!options.confirm)closePhfModal(true)});document.body.appendChild(root);setTimeout(function(){var b=root.querySelector('.phf-modal-btn.primary');if(b)b.focus()},20)})}
  function phfAlert(message,title,tone){return phfDialog(message,{title:title||'Thông báo',tone:tone||'',icon:tone==='danger'?'!':'✓'})}
  function phfConfirm(message,title,tone,okText){return phfDialog(message,{title:title||'Xác nhận thao tác',tone:tone||'warn',icon:'?',confirm:true,okText:okText||'Xác nhận',cancelText:'Quay lại'})}
  window.closePhfModal=closePhfModal;
  var XLSX_LOADING=null;
  function loadXlsxLib(){if(window.XLSX)return Promise.resolve(window.XLSX);if(XLSX_LOADING)return XLSX_LOADING;XLSX_LOADING=new Promise(function(resolve,reject){var sc=document.createElement('script');sc.src='assets/vendor/xlsx.full.min.js';sc.onload=function(){window.XLSX?resolve(window.XLSX):reject(new Error('Không khởi tạo được thư viện đọc Excel.'))};sc.onerror=function(){reject(new Error('Không tải được thư viện đọc Excel.'))};document.head.appendChild(sc)});return XLSX_LOADING}

  function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
  function read(k,f){try{var r=localStorage.getItem(k);return r?(JSON.parse(r)||f):f}catch(e){return f}}
  function write(k,v){try{localStorage.setItem(k,JSON.stringify(v||[]))}catch(e){}}
  function cleanEmail(v){return String(v||'').trim().toLowerCase()}
  function cleanPhone(v){return String(v||'').replace(/[^\d+]/g,'').trim()}
  function now(){try{return new Date().toLocaleString('vi-VN',{hour12:false})}catch(e){return new Date().toISOString()}}
  function uid(prefix){return prefix+'-'+Date.now()+'-'+Math.floor(Math.random()*9999)}
  function slug(s){s=String(s||'').toLowerCase();var map={'đ':'d','á':'a','à':'a','ả':'a','ã':'a','ạ':'a','ă':'a','ắ':'a','ằ':'a','ẳ':'a','ẵ':'a','ặ':'a','â':'a','ấ':'a','ầ':'a','ẩ':'a','ẫ':'a','ậ':'a','é':'e','è':'e','ẻ':'e','ẽ':'e','ẹ':'e','ê':'e','ế':'e','ề':'e','ể':'e','ễ':'e','ệ':'e','í':'i','ì':'i','ỉ':'i','ĩ':'i','ị':'i','ó':'o','ò':'o','ỏ':'o','õ':'o','ọ':'o','ô':'o','ố':'o','ồ':'o','ổ':'o','ỗ':'o','ộ':'o','ơ':'o','ớ':'o','ờ':'o','ở':'o','ỡ':'o','ợ':'o','ú':'u','ù':'u','ủ':'u','ũ':'u','ụ':'u','ư':'u','ứ':'u','ừ':'u','ử':'u','ữ':'u','ự':'u','ý':'y','ỳ':'y','ỷ':'y','ỹ':'y','ỵ':'y'};Object.keys(map).forEach(function(k){s=s.split(k).join(map[k])});return s.replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').toUpperCase()||'ITEM'}
  function staff(){return Array.isArray(window.PHF_EXISTING_STAFF)?window.PHF_EXISTING_STAFF:[]}
  function uniq(vals){var out=[],seen={};(vals||[]).forEach(function(v){v=String(v||'').trim();if(!v)return;var k=v.toLowerCase();if(!seen[k]){seen[k]=1;out.push(v)}});return out}
  function shortDeptName(d){return String(d||'').replace(/^Bộ phận\s+/i,'').trim()}
  function roleLabel(r){return r==='admin'?'Admin':(r==='manager'?'Quản lý':'Học viên')}
  function statusLabel(s){return s==='locked'?'Tạm khóa':(s==='inactive'?'Ngừng sử dụng':'Đang hoạt động')}
  function programLabel(p){return p==='phf_class'?'PHF Class':(p==='new_sales'?'Bán hàng mới':(p==='none'?'Chưa gán':'—'))}
  function actionCode(v){v=String(v||'').trim().toLowerCase();if(v==='update'||v.indexOf('cập')>=0||v.indexOf('cap')>=0)return'UPDATE';if(v==='lock'||v.indexOf('khóa')>=0||v.indexOf('khoa')>=0)return'LOCK';if(v==='unlock'||v.indexOf('mở')>=0||v.indexOf('mo')>=0)return'UNLOCK';return'CREATE'}
  function roleCode(v){v=String(v||'').trim().toLowerCase();if(v==='admin')return'admin';if(v==='manager'||v.indexOf('quản')>=0||v.indexOf('quan')>=0||v.indexOf('trưởng')>=0||v.indexOf('truong')>=0)return'manager';return'learner'}
  function statusCode(v){v=String(v||'').trim().toLowerCase();if(v==='locked'||v.indexOf('khóa')>=0||v.indexOf('khoa')>=0||v.indexOf('tạm')>=0||v.indexOf('tam')>=0)return'locked';if(v==='inactive'||v.indexOf('ngừng')>=0||v.indexOf('ngung')>=0||v.indexOf('nghỉ')>=0||v.indexOf('nghi')>=0)return'inactive';return'active'}
  function programCode(v){v=String(v||'').trim().toLowerCase();if(v==='phf_class'||v.indexOf('class')>=0)return'phf_class';if(v==='new_sales'||v.indexOf('bán hàng')>=0||v.indexOf('ban hang')>=0)return'new_sales';return'none'}
  function chip(text, cls){return '<span class="phf-chip '+(cls||'')+'">'+esc(text)+'</span>'}
  function roleChip(r){return chip(roleLabel(r),r==='admin'?'blue':(r==='manager'?'pink':''))}
  function statusChip(s,mustChange){if(mustChange&&s==='active')return chip('Cần đổi mật khẩu','warn');return chip(statusLabel(s),s==='locked'?'warn':(s==='inactive'?'muted':'done'))}
  function sessionRole(){try{return String((typeof window.phfGetSessionRole==='function'?window.phfGetSessionRole():'')||'').toLowerCase()}catch(e){return''}}
  function isAdmin(){return sessionRole()==='admin'}
  function requireAdminUi(){
    var role=sessionRole();
    if(!role){
      if(typeof window.phfGoLogin==='function')window.phfGoLogin();
      else phfAlert('Phiên đăng nhập chưa sẵn sàng. Vui lòng đăng nhập lại.','Chưa xác minh phiên','warn');
      return false;
    }
    if(role!=='admin'){
      phfAlert('Khu vực Quản trị tài khoản chỉ dành cho Admin.');
      return false;
    }
    return true;
  }
  function main(){return document.getElementById('mainLesson')||document.querySelector('main')||document.body}
  function setShell(){try{if(typeof window.phfHideIntroAndStopAuto==='function')window.phfHideIntroAndStopAuto()}catch(e){}try{if(typeof window.phfEnsureSharedShell==='function')window.phfEnsureSharedShell('admin')}catch(e){}try{if(typeof window.phfSetMainNavActive==='function')window.phfSetMainNavActive('admin')}catch(e){}var m=document.getElementById('miniStatus');if(m)m.textContent='Quản trị tài khoản';var t=document.getElementById('contextTitle');if(t)t.textContent='Quản trị tài khoản & danh mục';var s=document.getElementById('contextSub');if(s)s.textContent='Chuẩn hóa tài khoản, chi nhánh, phòng ban, vị trí và đối tượng đào tạo.';var a=document.getElementById('contextAction');if(a)a.textContent='Admin'}
  function currentAdminLabel(){try{var email=currentLoginEmail();var a=accounts().find(function(x){return cleanEmail(x.email)===email});return (a&&a.name?String(a.name):email)||'Admin'}catch(e){return'Admin'}}
  function logs(){var l=read(LOG,[]);if(!l.length)return'<div class="phf-acct-safe-logitem">Chưa có thao tác quản trị tài khoản.</div>';return l.slice(0,12).map(function(x){return'<div class="phf-acct-safe-logitem"><b>'+esc(x.at)+'</b>'+(x.actor?'<small> · '+esc(x.actor)+'</small>':'')+'<br>'+esc(x.text)+'</div>'}).join('')}
  function addLog(t){var l=read(LOG,[]);l.unshift({at:now(),actor:currentAdminLabel(),text:String(t||'')});write(LOG,l.slice(0,100))}

  function makeItem(id,name,extra){var x={id:id||uid('cat'),name:String(name||'').trim(),status:(extra&&extra.status)||'active',note:(extra&&extra.note)||''};if(extra)Object.keys(extra).forEach(function(k){x[k]=extra[k]});return x}
  function defaultBranches(){return [{id:'PL',name:'Phú Lợi',status:'active',note:'Chi nhánh mặc định'},{id:'NQ',name:'Ngô Quyền',status:'active',note:'Chi nhánh mặc định'},{id:'LT',name:'Lái Thiêu',status:'active',note:'Chi nhánh mặc định'}]}
  function defaultDepartments(){return uniq(staff().map(function(s){return s.department})).map(function(n){return makeItem('DEPT_'+slug(n),n,{status:'active',note:'Theo file nhân sự hiện hữu'})})}
  function isBoardDepartment(name){return sameText(name,'Ban giám đốc')||slug(name)==='BAN_GIAM_DOC'}
  function normalizePositionName(name,department){var n=trim(name).replace(/\s+/g,' ');if(!n)return'';var key=n.toLowerCase().replace(/\s*\/\s*/g,'/');if(key==='quản lý/trưởng ca'||key==='quan ly/truong ca')return String(department||'').toLowerCase().indexOf('bán hàng')>=0?'Trưởng ca':'Quản lý';if(key==='nhân viên'||key==='nhan vien')return'Nhân viên';if(/^trưởng bộ phận\s+/i.test(n))return'Trưởng bộ phận '+shortDeptName(n.replace(/^Trưởng bộ phận\s+/i,''));return n.replace(/TRƯỞNG CA/g,'Trưởng ca').replace(/NHÂN VIÊN/g,'Nhân viên')}
  function inferPositionLevel(name){var n=String(name||'').toLowerCase();if(n.indexOf('trưởng bộ phận')===0)return'TBP';if(n.indexOf('trưởng ca')>=0||n.indexOf('cửa hàng trưởng')>=0||n.indexOf('quản lý')>=0||n.indexOf('giám đốc')>=0)return'Quản lý';return'Nhân viên'}
  function defaultPositions(){var deps=defaultDepartments(), out=[];deps.forEach(function(d){var names=uniq(staff().filter(function(s){return String(s.department||'').toLowerCase()===String(d.name||'').toLowerCase()}).map(function(s){return normalizePositionName(s.position,d.name)}));if(!isBoardDepartment(d.name)){var tbp='Trưởng bộ phận '+shortDeptName(d.name);if(names.map(function(x){return x.toLowerCase()}).indexOf(tbp.toLowerCase())<0)names.push(tbp)}names.forEach(function(n){if(!n)return;var level=inferPositionLevel(n);out.push(makeItem('POS_'+slug(d.name+'_'+n),n,{department:d.name,level:level,isManager:level!=='Nhân viên',status:'active',note:'Vị trí công việc theo phòng ban'}))});});return out}
  function defaultAudiences(){return [makeItem('AUD_NEW','Nhân sự mới',{status:'active',note:'Nhân sự mới tham gia lộ trình đào tạo ban đầu'}),makeItem('AUD_EXISTING','Nhân sự hiện hữu',{status:'active',note:'Nhân sự đang làm tại PHF'}),makeItem('AUD_RETRAIN','Tái đào tạo',{status:'active',note:'Đào tạo lại/củng cố năng lực'}),makeItem('AUD_SUPPLEMENT','Đào tạo bổ sung',{status:'active',note:'Đào tạo thêm ngoài công việc chính'}),makeItem('AUD_PERIODIC','Đào tạo định kỳ',{status:'active',note:'Kiểm tra/ôn tập định kỳ'})]}
  function catalog(key, def){var l=read(key,null);if(Array.isArray(l)&&l.length)return l;var d=def();write(key,d);return d}
  function branches(){return catalog(BRANCH_KEY, defaultBranches)}
  function departments(){return catalog(DEPT_KEY, defaultDepartments)}
  function positions(){return catalog(POS_KEY, defaultPositions)}
  function audiences(){return catalog(AUD_KEY, defaultAudiences)}
  function cleanupPositionCatalog(){try{if(localStorage.getItem(POSITION_CLEANUP_KEY)==='done')return;var list=positions(),ac=accounts(),changed=false,accountChanged=false,out=[],seen={};list.forEach(function(p){var oldName=trim(p.name),oldDept=trim(p.department),newName=normalizePositionName(oldName,oldDept);if(isBoardDepartment(oldDept)&&sameText(oldName,'Trưởng bộ phận Ban giám đốc'))newName='Quản lý';if(!newName)return;var key=slug(oldDept)+'|'+slug(newName);ac.forEach(function(a){if(sameText(a.department,oldDept)&&sameText(a.position,oldName)&&!sameText(a.position,newName)){a.position=newName;accountChanged=true}});p.name=newName;p.level=inferPositionLevel(newName);p.isManager=p.level!=='Nhân viên';p.note=p.note==='Theo file nhân sự + TBP phòng ban'?'Vị trí công việc theo phòng ban':(p.note||'');if(!seen[key]){seen[key]=p;out.push(p)}else{var keep=seen[key];if(keep.status==='inactive'&&p.status!=='inactive')keep.status='active';changed=true}if(!sameText(oldName,newName))changed=true});departments().forEach(function(d){if(isBoardDepartment(d.name))return;var tbp='Trưởng bộ phận '+shortDeptName(d.name),key=slug(d.name)+'|'+slug(tbp);if(!seen[key]){var item=makeItem('POS_'+slug(d.name+'_'+tbp),tbp,{department:d.name,level:'TBP',isManager:true,status:'active',note:'Vị trí công việc theo phòng ban'});seen[key]=item;out.push(item);changed=true}});if(changed)write(POS_KEY,out);if(accountChanged)saveAccounts(ac);localStorage.setItem(POSITION_CLEANUP_KEY,'done');if(changed||accountChanged)addLog('Chuẩn hóa danh mục vị trí công việc theo phòng ban')}catch(e){}}
  function activeNames(list){return (list||[]).filter(function(x){return x.status!=='inactive'}).map(function(x){return x.name})}
  function selectOptions(vals, selected){return (vals||[]).map(function(v){return '<option value="'+esc(v)+'" '+(String(v)===String(selected)?'selected':'')+'>'+esc(v)+'</option>'}).join('')}
  function positionNamesForDept(dept){return activeNames(positions().filter(function(p){return !dept||String(p.department||'').toLowerCase()===String(dept||'').toLowerCase()}))}

  function normalizeAccount(a){a=a||{};a.accountType=String(a.accountType||(a.metadata&&a.metadata.accountType)||'employee');a.email=cleanEmail(a.email);a.phone=cleanPhone(a.phone);a.role=a.role||'learner';a.status=a.status||'active';a.branch=a.branch||a.location||'';a.department=a.department||'';a.position=a.position||'';a.trainingAudience=a.trainingAudience||a.audience||a.suggestedPurposeGroup||'';if(a.trainingAudience==='Nhân viên cũ')a.trainingAudience='Nhân sự hiện hữu';if(a.trainingAudience==='Nhân viên mới')a.trainingAudience='Nhân sự mới';a.defaultProgram=a.defaultProgram||a.program||'';a.hubAssignmentStatus=normalizeHubAssignmentStatus(a.hubAssignmentStatus||a.hub_assignment_status,a.trainingAudience);return a}
  function accounts(){var l=read(KEY,null);if(Array.isArray(l))return l.map(normalizeAccount);write(KEY,[]);return []}
  function saveAccounts(l){write(KEY,(l||[]).map(normalizeAccount));try{if(typeof window.phfServerAuthSyncAccounts==='function')setTimeout(function(){window.phfServerAuthSyncAccounts()},0)}catch(e){}}
  function trim(v){return String(v==null?'':v).trim()}
  function emailOk(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanEmail(v))}
  function phoneDigits(v){return cleanPhone(v).replace(/\D/g,'')}
  function sameText(a,b){return trim(a).toLowerCase()===trim(b).toLowerCase()}
