  function staffEmails(s){return uniq([s.suggestedEmail,s.workEmail,s.personalEmail].map(cleanEmail).filter(Boolean))}
  function staffLinkInfo(s){var list=accounts().filter(function(a){return a.accountType!=='system_admin'}),matches=[];function add(a,reason){if(!a)return;var found=matches.find(function(m){return m.account.id===a.id});if(found){if(found.reasons.indexOf(reason)<0)found.reasons.push(reason)}else matches.push({account:a,reasons:[reason]})}var staffId=String(s.id||s.employeeId||'');if(staffId){list.forEach(function(a){if(a.employeeId&&String(a.employeeId)===staffId)add(a,'Hồ sơ')})}if(matches.length===1)return{state:'linked',account:matches[0].account,reasons:matches[0].reasons};if(matches.length>1)return{state:'review',matches:matches};list=list.filter(function(a){return !a.employeeId});if(s.employeeCode){list.forEach(function(a){if(a.employeeCode&&sameText(a.employeeCode,s.employeeCode))add(a,'Mã NV')})}staffEmails(s).forEach(function(email){list.forEach(function(a){if(cleanEmail(a.email)===email)add(a,'Email')})});if(phoneDigits(s.phone)){list.forEach(function(a){if(phoneDigits(a.phone)&&phoneDigits(a.phone)===phoneDigits(s.phone))add(a,'SĐT')})}if(matches.length===1)return{state:'linked',account:matches[0].account,reasons:matches[0].reasons};if(matches.length>1)return{state:'review',matches:matches};return{state:'unlinked'}}
